const io=new IntersectionObserver(es=>es.forEach((e,i)=>{if(e.isIntersecting){setTimeout(()=>e.target.classList.add('in'),i*100);setTimeout(()=>e.target.classList.add('rdy'),i*100+900);io.unobserve(e.target)}}),{threshold:.18});
